import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"49、【革】 離下兌上","description":"周易闡真 - 49、【革】 離下兌上","frontmatter":{"title":"49、【革】 離下兌上","description":"周易闡真 - 49、【革】 離下兌上"},"headers":[],"relativePath":"classics/chanzhen/050.md","filePath":"classics/chanzhen/050.md"}'),s={name:"classics/chanzhen/050.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：革，水火相息，二女同居，其志不相得曰革。已日乃孚，革而信之。文明以說，大亨以正。革而當，其悔乃亡。天地革而四時成，湯武革命，順乎天而應乎人。革之時大矣哉！</p></blockquote><h1 id="_49、【革】-離下兌上" tabindex="-1">49、【革】 離下兌上 <a class="header-anchor" href="#_49、【革】-離下兌上" aria-label="Permalink to “49、【革】 離下兌上”">​</a></h1><p>初九：鞏用黃牛之革。</p><p>六二：己日乃革之，徵吉，無咎。</p><p>九三：徵兇，貞厲。革言三就，有孚。</p><p>九四：悔亡，有孚改命，吉。</p><p>九五：大人虎變，未佔有孚。</p><p>上六：君子豹變，小人革面。徵兇，居貞吉。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：澤中有火，革。君子以治歷明時。</p><p>革者，更變也。上兌澤，下離火，是澤中有火也。澤本溼，火本燥。溼太過，而有火燥之；燥太過，而有溼潤之。澤火一處，溼燥相濟，革之象也。</p><p>君子有見於此，知人之立身處世，不能因事制宜、隨時遷就者，皆由不明天道變化之理、陰陽進退之節。以是分春夏秋冬、二十四氣、七十二候，治而為歷，以明五行之運氣，各有其時，使人人順天隨時，變革太過之行，歸於中正耳。蓋天有運行之時，人有當行之道。時有遷移，道有變化。變化之道，即與時偕行之道。與時偕行，進退存亡不失其正，亦一天行矣。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>革者，去而不用之義，所以去舊也。卦德上兌悅，下離明，悅本於明，以明制悅，悅而不得有妄，明而不得有昧，明中出悅，悅中有明，故謂革。卦象兌為西方金，離為南方火，以火鍊金，金遇火而生明返陽，火遇金而入庫返本，亦革之義。此煅煉陰氣之卦，承上困卦而來。困者，險中出悅，所以取坎中真陽以出險也。然能取坎中真陽，而不能復離中真陰，金丹不結，仍不得悅，此明中出悅之道，不可缺也。明中出悅，煅煉陰氣之功也。煅煉陰氣，是煅煉己之私慾，無我之謂也。</p><p>人為萬物之靈，秉天地陰陽五行之正氣而生。當有生之初，不識不知，順帝之則，至善無惡，真性炯炯，虛靈不昧，喜怒哀樂，不著於心，富貴窮通，不動其意，虎兕不能傷，刀兵不能加，水火不能浸，生死不能累，飢只食，寒只衣，無思無慮，德本明也。及至二八，陽極生陰，後天用事，氣質之性發，知識之竅開。當斯時也，惟天縱上智之聖人，先天而天弗違，後天而奉天時，能保先天之真，而不為後天所傷。其次中下之人，鮮有不為後天所規弄者。</p><p>自此而後，百憂感其心，萬事勞其形，認假為真，棄正入邪，日復一日，年復一年，性相近而習相遠，明德有傷，新者積而成舊，淨者染而有垢，此舊染之汙，所由來也。原其有舊染之汙者，皆由有己，一有其己，則道心昧而人心生，明非所明，悅非所悅，順其所欲，無所不至矣。</p><p>革者，即革其己之不明，以復於明耳。然欲革其己之不明，須要己先能明。己既能明，則信於革，而己之不明可革矣。是以革之道，己日乃孚也。</p><p>日者，明之象；孚者，信之謂。不明不信，能明乃信，明之信之，初念已真，未有不能革己者。是以革有元亨之道也。但革雖有元亨之道，又須革之得正。若是非不分，真假罔辨，一概革之，入於頑空寂滅之學，不正即不利，不利仍是不元亨，惟以正而革，克己復禮，去妄存誠，煅去後天一切滓質，現出先天一靈真性。到此地位，還元返本，渾然天理，純白無玷，有己之悔可亡矣。是道也，非知之艱，行之維艱，是在人之能信於革耳。</p><p>初九，剛而不明，不能逆革其內，乃順革於外，如鞏用黃牛之革，顧外失內，固執不通。此捨本逐末之革也。</p><p>六二，虛心自處，明於革而先能去其私慾。私慾能去，則無己。無己則有人，有人則以己求人，即能實腹。實腹而己愈明，是以徵吉，而且無咎。此虛心求明之革也。</p><p>九三，剛而太過，只知革人，不知革己，雖革事得正，亦有兇屬。蓋以不能革己，即欲革人，不但人不受我革，且將有言來革我，雖欲不自革而不能。是以革言三就也。三就之革，可信其終於不能革己矣。此自大自尊之革也。</p><p>九四，有剛不用，是以有悔可亡，悔出於不信革己。若信革己，剛即能柔，可以變化氣質，而不為陰陽所拘，豈僅有己之悔可亡，方且有改命之吉。此剛以柔用之革也。</p><p>九五，陽剛中正，主宰在內，扶陽抑陰，開生門、閉死戶，留人道、塞鬼路，一切客氣，自消自化，如虎威常在，不變之變，無容佔信其已革矣。此大人用剛有為之革也。</p><p>上六，在革之終。柔而得正，煉己功勤，虛極靜篤，如豹不威之變，誠中達外，氣質俱化，根塵全消，淨倮倮、赤灑灑，形神俱妙，與道合真矣。此君子用柔無為之革也。然用柔無為之革，惟有信心之君子能之，一切不信心之小人，則不能。蓋小人者，革面不革心，志念不堅，有始無終，必落空亡而致兇。君子者，永居於貞，志念長久，愈久愈力，終必成道而得吉。此邪正結果之革也。</p><p>六爻俱有革道，是非不等，總以無己為歸著。若稍有一點己在，革去而又來，陰氣不盡，陽氣不純，古經所謂“七返還丹，在人先須煉己待時”者，正欲其革去一切舊染之汙，不使有絲毫之疵，留於方寸之中也。</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
